B.b1D=new A.cf("q_tafkheem_tarqeeq_raaa_sakena_1","\u0627\u0644\u0631\u0627\u0621 \u0627\u0644\u0633\u0627\u0643\u0646\u0629","\u0627\u0644\u062a\u0641\u062e\u064a\u0645 \u0648\u0627\u0644\u062a\u0631\u0642\u064a\u0642",B.a0,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645 \u0648\u0627\u0644\u062a\u0631\u0642\u064a\u0642 \u0641\u064a \u0627\u0644\u0631\u0627\u0621 \u0627\u0644\u0633\u0627\u0643\u0646\u0629 \u0641\u0642\u0637",B.aaG,"q_tafkheem_tarqeeq_raaa_others_1",B.ak7)
B.aYf=new A.w("\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u062c\u0650\u0639\u0650\u064a\u0653 ) \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0671\u0631\u06e1\u062c\u0650\u0639\u0650\u064a\u0653 \u0625\u0650\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0643\u0650 \u0631\u064e\u0627\u0636\u0650\u064a\u064e\u0629\u064b \u0645\u0651\u064e\u0631\u06e1\u0636\u0650\u064a\u0651\u064e\u0629\u064b )",B.aD,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645","\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u062a\u064f\u0641\u062e\u0651\u0645 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0639\u0627\u0631\u0636 \u0645\u062a\u0635\u0644\u060c \u0641\u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u062c\u0650\u0639\u0650\u064a\u0653 ) \u062a\u064f\u0641\u062e\u0651\u0645 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0639\u0627\u0631\u0636 \u0645\u062a\u0635\u0644\u060c \u0641\u0627\u0644\u0643\u0633\u0631 \u064a\u0639\u0631\u0636 \u0644\u0644\u0647\u0645\u0632\u0629 \u0627\u0644\u0648\u0635\u0644\u064a\u0629 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0641\u0642\u0637 ( \u0671\u0650 )\u060c \u0623\u0645\u0627 \u0639\u0646\u062f \u0648\u0635\u0644 \u0627\u0644\u0622\u064a\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0628\u0647\u0627 { \u064a\u064e\u0670\u0653\u0623\u064e\u064a\u0651\u064e\u062a\u064f\u0647\u064e\u0627 \u0671\u0644\u0646\u0651\u064e\u0641\u06e1\u0633\u064f \u0671\u0644\u06e1\u0645\u064f\u0637\u06e1\u0645\u064e\u0626\u0650\u0646\u0651\u064e\u0629\u064f (\u0662\u0667) \u0671\u0631\u06e1\u062c\u0650\u0639\u0650\u064a\u0653 } \u0641\u064a\u0643\u0648\u0646 \u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0627\u0644\u062a\u0641\u062e\u064a\u0645 \u0623\u064a\u0636\u064b\u0627 \u0644\u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u0633\u0627\u0643\u0646\u0629 \u0648\u0627\u0644\u0647\u0645\u0632\u0629 \u0627\u0644\u0648\u0635\u0644\u064a\u0629 \u062a\u064f\u062d\u0630\u0641 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644 \u0648\u0645\u0627 \u0642\u0628\u0644\u0647\u0627 \u0645\u0636\u0645\u0648\u0645 ( \u0640\u0629\u064f )")
B.b0e=new A.w("\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0628\u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u0643\u064e\u0628\u064f\u0648\u0627\u0652 ) \u0645\u0646 \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0648\u064e\u0642\u064e\u0627\u0644\u064e \u0671\u0631\u06e1\u0643\u064e\u0628\u064f\u0648\u0627\u0652 \u0641\u0650\u064a\u0647\u064e\u0627 )",B.aD,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645","\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u062a\u064f\u0641\u062e\u0651\u0645 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0639\u0627\u0631\u0636 \u0645\u062a\u0635\u0644\u060c \u0641\u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u0643\u064e\u0628\u064f\u0648\u0627\u0652 ) \u062a\u064f\u0641\u062e\u0651\u0645 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0639\u0627\u0631\u0636 \u0645\u062a\u0635\u0644\u060c \u0641\u0627\u0644\u0643\u0633\u0631 \u064a\u0639\u0631\u0636 \u0644\u0644\u0647\u0645\u0632\u0629 \u0627\u0644\u0648\u0635\u0644\u064a\u0629 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0641\u0642\u0637 ( \u0671\u0650 )\u060c \u0623\u0645\u0627 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644 \u0641\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0647\u0648 \u0627\u0644\u062a\u0641\u062e\u064a\u0645 \u0623\u064a\u0636\u064b\u0627 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0645\u0627 \u0642\u0628\u0644\u0647\u0627 \u0645\u0641\u062a\u0648\u062d ( \u0644\u064e ) \u0644\u0623\u0646 \u0627\u0644\u0647\u0645\u0632\u0629 \u0627\u0644\u0648\u0635\u0644\u064a\u0629 \u062a\u064f\u062d\u0630\u0641 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644")
B.aZX=new A.w("\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u062d\u064e\u0645\u06e1\u0647\u064f\u0645\u064e\u0627 ) \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0631\u0651\u064e\u0628\u0651\u0650 \u0671\u0631\u06e1\u062d\u064e\u0645\u06e1\u0647\u064f\u0645\u064e\u0627 )",B.aD,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645","\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u062a\u064f\u0641\u062e\u0651\u0645 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0623\u0648 \u0639\u0627\u0631\u0636 \u0645\u0646\u0641\u0635\u0644\u060c \u0623\u064a \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 \u0648\u0627\u0644\u0643\u0633\u0631\u0629 \u0641\u064a \u0643\u0644\u0645\u0629 \u0623\u062e\u0631\u0649\u060c \u0641\u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u062d\u064e\u0645\u06e1\u0647\u064f\u0645\u064e\u0627 ) \u062a\u064f\u0641\u062e\u0651\u0645 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u0646\u0641\u0635\u0644 \u0641\u064a \u0643\u0644\u0645\u0629 \u0623\u062e\u0631\u0649 ( \u0631\u0651\u064e\u0628\u0651\u0650 )\u060c \u0647\u0630\u0627 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644\u060c \u0623\u0645\u0627 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0628\u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u062d\u064e\u0645\u06e1\u0647\u064f\u0645\u064e\u0627 ) \u0641\u0625\u0646 \u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0647\u0648 \u0627\u0644\u062a\u0641\u062e\u064a\u0645 \u0623\u064a\u0636\u064b\u0627 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0639\u0627\u0631\u0636 \u0645\u062a\u0635\u0644\u060c \u0641\u0627\u0644\u0643\u0633\u0631 \u064a\u0639\u0631\u0636 \u0644\u0644\u0647\u0645\u0632\u0629 \u0627\u0644\u0648\u0635\u0644\u064a\u0629 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0641\u0642\u0637 ( \u0671\u0650 )")
B.aYZ=new A.w("\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u062a\u064e\u0627\u0628\u064f\u0648\u0653\u0627\u0652 ) \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0623\u064e\u0645\u0650 \u0671\u0631\u06e1\u062a\u064e\u0627\u0628\u064f\u0648\u0653\u0627\u0652 )",B.aD,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645","\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u062a\u064f\u0641\u062e\u0651\u0645 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0623\u0648 \u0639\u0627\u0631\u0636 \u0645\u0646\u0641\u0635\u0644\u060c \u0623\u064a \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 \u0648\u0627\u0644\u0643\u0633\u0631\u0629 \u0641\u064a \u0643\u0644\u0645\u0629 \u0623\u062e\u0631\u0649\u060c \u0641\u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u062a\u064e\u0627\u0628\u064f\u0648\u0653\u0627\u0652 ) \u062a\u064f\u0641\u062e\u0651\u0645 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0639\u0627\u0631\u0636 \u0645\u0646\u0641\u0635\u0644 \u0641\u064a \u0643\u0644\u0645\u0629 \u0623\u062e\u0631\u0649 ( \u0623\u064e\u0645\u0650 )\u060c \u0647\u0630\u0627 \u0639\u0646\u062f \u0627\u0644\u0648\u0635\u0644\u060c \u0623\u0645\u0627 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0628\u0643\u0644\u0645\u0629 ( \u0671\u0631\u06e1\u062a\u064e\u0627\u0628\u064f\u0648\u0653\u0627\u0652 ) \u0641\u0625\u0646 \u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0647\u0648 \u0627\u0644\u062a\u0641\u062e\u064a\u0645 \u0623\u064a\u0636\u064b\u0627 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0639\u0627\u0631\u0636 \u0645\u062a\u0635\u0644\u060c \u0641\u0627\u0644\u0643\u0633\u0631 \u064a\u0639\u0631\u0636 \u0644\u0644\u0647\u0645\u0632\u0629 \u0627\u0644\u0648\u0635\u0644\u064a\u0629 \u0639\u0646\u062f \u0627\u0644\u0627\u0628\u062a\u062f\u0627\u0621 \u0641\u0642\u0637 ( \u0671\u0650 )")
B.aXz=new A.w("\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0644\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0650 ) \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0650 )",B.aD,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645","\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u062a\u064f\u0641\u062e\u0651\u0645 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u062a\u0635\u0644\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0628\u0639\u062f\u0647\u0627 \u062d\u0631\u0641 \u0627\u0633\u062a\u0639\u0644\u0627\u0621 \u0645\u062a\u0635\u0644 \u063a\u064a\u0631 \u0645\u0643\u0633\u0648\u0631\u060c \u0641\u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0644\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0650 ) \u062a\u064f\u0641\u062e\u0651\u0645 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u062a\u0635\u0644\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0628\u0639\u062f\u0647\u0627 \u062d\u0631\u0641 ( \u0627\u0644\u0635\u0627\u062f ) \u0648\u0647\u0648 \u0645\u0646 \u062d\u0631\u0648\u0641 \u0627\u0644\u0627\u0633\u062a\u0639\u0644\u0627\u0621 ( \u062e\u064f\u0635\u0651\u064e \u0636\u063a\u0652\u0637\u064d \u0642\u0650\u0638\u0652 ) \u063a\u064a\u0631 \u0645\u0643\u0633\u0648\u0631 \u0641\u064a \u0643\u0644\u0645\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0642\u062f \u0648\u0631\u062f \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u062e\u0645\u0633 \u0643\u0644\u0645\u0627\u062a \u0641\u0642\u0637 \u062a\u0646\u0637\u0628\u0642 \u0639\u0644\u064a\u0647\u0627 \u0647\u0630\u0647 \u0627\u0644\u0642\u0627\u0639\u062f\u0629\u060c \u0647\u064a ( \u0644\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0650 \u060c \u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u060c \u0648\u064e\u0625\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u060c \u0642\u0650\u0631\u06e1\u0637\u064e\u0627\u0633\u064d \u060c \u0641\u0650\u0631\u06e1\u0642\u064e\u0629\u064d )")
B.aYQ=new A.w("\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 ) \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0625\u0650\u0646\u0651\u064e \u062c\u064e\u0647\u064e\u0646\u0651\u064e\u0645\u064e \u0643\u064e\u0627\u0646\u064e\u062a\u06e1 \u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 )",B.aD,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645","\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u062a\u064f\u0641\u062e\u0651\u0645 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u062a\u0635\u0644\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0628\u0639\u062f\u0647\u0627 \u062d\u0631\u0641 \u0627\u0633\u062a\u0639\u0644\u0627\u0621 \u0645\u062a\u0635\u0644 \u063a\u064a\u0631 \u0645\u0643\u0633\u0648\u0631\u060c \u0641\u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 ) \u062a\u064f\u0641\u062e\u0651\u0645 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u062a\u0635\u0644\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0628\u0639\u062f\u0647\u0627 \u062d\u0631\u0641 ( \u0627\u0644\u0635\u0627\u062f ) \u0648\u0647\u0648 \u0645\u0646 \u062d\u0631\u0648\u0641 \u0627\u0644\u0627\u0633\u062a\u0639\u0644\u0627\u0621 ( \u062e\u064f\u0635\u0651\u064e \u0636\u063a\u0652\u0637\u064d \u0642\u0650\u0638\u0652 ) \u063a\u064a\u0631 \u0645\u0643\u0633\u0648\u0631 \u0641\u064a \u0643\u0644\u0645\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0642\u062f \u0648\u0631\u062f \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u062e\u0645\u0633 \u0643\u0644\u0645\u0627\u062a \u0641\u0642\u0637 \u062a\u0646\u0637\u0628\u0642 \u0639\u0644\u064a\u0647\u0627 \u0647\u0630\u0647 \u0627\u0644\u0642\u0627\u0639\u062f\u0629\u060c \u0647\u064a ( \u0644\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0650 \u060c \u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u060c \u0648\u064e\u0625\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u060c \u0642\u0650\u0631\u06e1\u0637\u064e\u0627\u0633\u064d \u060c \u0641\u0650\u0631\u06e1\u0642\u064e\u0629\u064d )")
B.b_S=new A.w("\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a ( \u0648\u064e\u0625\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 ) \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0648\u064e\u0625\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u0644\u0651\u0650\u0645\u064e\u0646\u06e1 \u062d\u064e\u0627\u0631\u064e\u0628\u064e \u0671\u0644\u0644\u0651\u064e\u0647\u064e \u0648\u064e\u0631\u064e\u0633\u064f\u0648\u0644\u064e\u0647\u064f\u06e5 )",B.aD,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645","\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u062a\u064f\u0641\u062e\u0651\u0645 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u062a\u0635\u0644\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0628\u0639\u062f\u0647\u0627 \u062d\u0631\u0641 \u0627\u0633\u062a\u0639\u0644\u0627\u0621 \u0645\u062a\u0635\u0644 \u063a\u064a\u0631 \u0645\u0643\u0633\u0648\u0631\u060c \u0641\u0627\u0644\u0631\u0627\u0621 \u0641\u064a ( \u0648\u064e\u0625\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 ) \u062a\u064f\u0641\u062e\u0651\u0645 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u062a\u0635\u0644\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0628\u0639\u062f\u0647\u0627 \u062d\u0631\u0641 ( \u0627\u0644\u0635\u0627\u062f ) \u0648\u0647\u0648 \u0645\u0646 \u062d\u0631\u0648\u0641 \u0627\u0644\u0627\u0633\u062a\u0639\u0644\u0627\u0621 ( \u062e\u064f\u0635\u0651\u064e \u0636\u063a\u0652\u0637\u064d \u0642\u0650\u0638\u0652 ) \u063a\u064a\u0631 \u0645\u0643\u0633\u0648\u0631 \u0641\u064a \u0643\u0644\u0645\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0642\u062f \u0648\u0631\u062f \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u062e\u0645\u0633 \u0643\u0644\u0645\u0627\u062a \u0641\u0642\u0637 \u062a\u0646\u0637\u0628\u0642 \u0639\u0644\u064a\u0647\u0627 \u0647\u0630\u0647 \u0627\u0644\u0642\u0627\u0639\u062f\u0629\u060c \u0647\u064a ( \u0644\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0650 \u060c \u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u060c \u0648\u064e\u0625\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u060c \u0642\u0650\u0631\u06e1\u0637\u064e\u0627\u0633\u064d \u060c \u0641\u0650\u0631\u06e1\u0642\u064e\u0629\u064d )")
B.aXB=new A.w("\u062d\u0643\u0645 \u0627\u0644\u0631\u0627\u0621 \u0641\u064a \u0643\u0644\u0645\u0629 ( \u0642\u0650\u0631\u06e1\u0637\u064e\u0627\u0633\u064d ) \u0641\u064a \u0642\u0648\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: ( \u0643\u0650\u062a\u064e\u0670\u0628\u064b\u0627 \u0641\u0650\u064a \u0642\u0650\u0631\u06e1\u0637\u064e\u0627\u0633\u064d )",B.aD,"\u0627\u0644\u062a\u0641\u062e\u064a\u0645","\u0627\u0644\u0642\u0627\u0639\u062f\u0629 \u0623\u0646 \u0627\u0644\u0631\u0627\u0621 \u062a\u064f\u0641\u062e\u0651\u0645 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u062a\u0635\u0644\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0628\u0639\u062f\u0647\u0627 \u062d\u0631\u0641 \u0627\u0633\u062a\u0639\u0644\u0627\u0621 \u0645\u062a\u0635\u0644 \u063a\u064a\u0631 \u0645\u0643\u0633\u0648\u0631\u060c \u0641\u0627\u0644\u0631\u0627\u0621 \u0641\u064a ( \u0642\u0650\u0631\u06e1\u0637\u064e\u0627\u0633\u064d ) \u062a\u064f\u0641\u062e\u0651\u0645 \u0644\u0623\u0646\u0647\u0627 \u0633\u0627\u0643\u0646\u0629 \u0648\u0642\u0628\u0644\u0647\u0627 \u0643\u0633\u0631 \u0623\u0635\u0644\u064a \u0645\u062a\u0635\u0644\u060c \u0648\u0644\u0643\u0646 \u0648\u0642\u0639 \u0628\u0639\u062f\u0647\u0627 \u062d\u0631\u0641 ( \u0627\u0644\u0637\u0627\u0621 ) \u0648\u0647\u0648 \u0645\u0646 \u062d\u0631\u0648\u0641 \u0627\u0644\u0627\u0633\u062a\u0639\u0644\u0627\u0621 ( \u062e\u064f\u0635\u0651\u064e \u0636\u063a\u0652\u0637\u064d \u0642\u0650\u0638\u0652 ) \u063a\u064a\u0631 \u0645\u0643\u0633\u0648\u0631 \u0641\u064a \u0643\u0644\u0645\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0648\u0642\u062f \u0648\u0631\u062f \u0641\u064a \u0627\u0644\u0642\u0631\u0622\u0646 \u062e\u0645\u0633 \u0643\u0644\u0645\u0627\u062a \u0641\u0642\u0637 \u062a\u0646\u0637\u0628\u0642 \u0639\u0644\u064a\u0647\u0627 \u0647\u0630\u0647 \u0627\u0644\u0642\u0627\u0639\u062f\u0629\u060c \u0647\u064a ( \u0644\u064e\u0628\u0650\u0671\u0644\u06e1\u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u0650 \u060c \u0645\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u060c \u0648\u064e\u0625\u0650\u0631\u06e1\u0635\u064e\u0627\u062f\u064b\u0627 \u060c \u0642\u0650\u0631\u06e1\u0637\u064e\u0627\u0633\u064d \u060c \u0641\u0650\u0631\u06e1\u0642\u064e\u0629\u064d )")
