B.b_q=new A.w("\u0644\u0645\u0627\u0630\u0627 \u0633\u064f\u0645\u0651\u064a\u064e \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632 \u0628\u0627\u0644\u0645\u0646\u0641\u0635\u0644",B.a9Z,"\u0644\u0627\u0646\u0641\u0635\u0627\u0644 \u0627\u0644\u0647\u0645\u0632\u0629 \u0639\u0646 \u062d\u0631\u0641 \u0627\u0644\u0645\u062f","\u0633\u064f\u0645\u0651\u064a\u064e \u0628\u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0644\u0627\u0646\u0641\u0635\u0627\u0644 \u0627\u0644\u0647\u0645\u0632\u0629 \u0639\u0646 \u062d\u0631\u0641 \u0627\u0644\u0645\u062f\u060c \u0641\u062d\u0631\u0641 \u0627\u0644\u0645\u062f \u064a\u0643\u0648\u0646 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0643\u0644\u0645\u0629 \u0648\u0627\u0644\u0647\u0645\u0632\u0629 \u062a\u0643\u0648\u0646 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0643\u0644\u0645\u0629 \u0627\u0644\u062a\u064a \u0628\u0639\u062f\u0647\u0627")
B.a4U=A.a(s(["\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e","\u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0653\u0621\u064e","\u0623\u064f\u0648\u0652\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u06e1"]),t.s)
B.aZs=new A.w("\u0645\u0646 \u0623\u0645\u062b\u0644\u0629 \u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632",B.a4U,"\u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e","\u0627\u0644\u0645\u062f \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0627\u0644\u062c\u0627\u0626\u0632 \u064a\u0643\u0648\u0646 \u0639\u0646\u062f\u0645\u0627 \u064a\u0623\u062a\u064a \u0628\u0639\u062f \u062d\u0631\u0641 \u0627\u0644\u0645\u062f \u0647\u0645\u0632\u0629 \u0645\u0646\u0641\u0635\u0644\u0629 \u0641\u064a \u0643\u0644\u0645\u0629 \u0623\u062e\u0631\u0649 \u0645\u062b\u0644 ( \u0625\u0650\u0646\u0651\u064e\u0627\u0653 \u0623\u064e\u0639\u06e1\u0637\u064e\u064a\u06e1\u0646\u064e\u0670\u0643\u064e ) \u0641\u0642\u062f \u0623\u062a\u062a \u0647\u0645\u0632\u0629 \u0645\u0646\u0641\u0635\u0644\u0629 \u0628\u0639\u062f \u062d\u0631\u0641 \u0627\u0644\u0645\u062f ( \u0627\u0644\u0623\u0644\u0641 )\u060c \u0623\u0645\u0627 \u0641\u064a ( \u062d\u064f\u0646\u064e\u0641\u064e\u0627\u0653\u0621\u064e - \u0623\u064f\u0648\u0652\u0644\u064e\u0670\u0653\u0626\u0650\u0643\u064e ) \u0641\u0627\u0644\u0647\u0645\u0632\u0629 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0643\u0644\u0645\u0629 \u0645\u0639 \u062d\u0631\u0641 \u0627\u0644\u0645\u062f")
